pred_sql:
SELECT School, MailZip
FROM schools
WHERE AdmFName1 = 'Avetik' AND AdmLName1 = 'Atoian';

SELECT StatusType, COUNT(*) 
FROM schools 
WHERE County = 'Alpine' AND (StatusType = 'Active' OR StatusType = 'Closed') AND `School Type` = 'District Community Day Schools';

SELECT layout 
FROM cards 
WHERE keywords LIKE '%Flying%';

SELECT DISTINCT type
FROM foreign_data
WHERE language = 'German';

SELECT COUNT(*) 
FROM Player 
WHERE player_name LIKE 'Aaron%' AND birthday > '1990-12-31';

SELECT T1.A2, T1.A3
FROM district AS T1
WHERE T1.A10 = (SELECT MAX(A10) FROM district WHERE A8 LIKE '1996%');

SELECT COUNT(*) 
FROM card 
WHERE type = 'classic';

SELECT SUM(CASE WHEN A3 = 'East Bohemia' THEN 1 ELSE 0 END) - SUM(CASE WHEN A3 = 'North Bohemia' THEN 1 ELSE 0 END) AS difference
FROM district
WHERE A8 = 1996;

SELECT COUNT(wins) 
FROM driverStandings 
WHERE position = 91;

SELECT label FROM molecule WHERE molecule_id NOT IN (
    SELECT molecule_id FROM atom WHERE element = 'sn'
);

SELECT CAST(SUM(CASE WHEN element = 'h' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage
FROM atom
WHERE molecule_id = 'TR206';
